#include <iostream>
using namespace std;

int main() {
    int i = 1;  // 1. Initializare contor

    while (i <= 10) {  // 2. Condiție de continuare
        cout << i << " ";  // 3. Actiune
        i++;  // 4. Modificare contor (ESENȚIAL!)
    }

    cout << endl << "Gata!" << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int i = 1;
    int suma = 0;

    while (i <= 100) {
        suma = suma + i;  // sau: suma += i;
        i++;
    }

    cout << "Suma numerelor de la 1 la 100 este: " << suma << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int numar;
    cout << "Introdu numere (0 pentru stop): " << endl;

    cin >> numar;
    while (numar != 0) {
        cout << "Ai introdus: " << numar << endl;
        cin >> numar;
    }

    cout << "La revedere!" << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int i = 1;

    while (i <= 10) {
        cout << i << " ";
        // GRESIT: am uitat i++!
        // Bucla rulează la infinit, afisand 1 1 1 1 1...
    }

    return 0;
}

